CREATE TYPE "AutomationStatus" AS ENUM ('DRAFT','ACTIVE','PAUSED','ARCHIVED');
CREATE TYPE "AutomationExecutionStatus" AS ENUM ('PENDING','RUNNING','SUCCEEDED','FAILED','SKIPPED');
CREATE TABLE "Automation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"createdById" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"status" "AutomationStatus" NOT NULL DEFAULT 'DRAFT',"triggerType" TEXT NOT NULL,"triggerConfig" JSONB NOT NULL,"conditions" JSONB NOT NULL,"actions" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"archivedAt" TIMESTAMP(3),CONSTRAINT "Automation_business_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,CONSTRAINT "Automation_createdBy_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "Automation_businessId_id_key" ON "Automation"("businessId","id");
CREATE UNIQUE INDEX "Automation_businessId_name_key" ON "Automation"("businessId","name");
CREATE INDEX "Automation_businessId_status_idx" ON "Automation"("businessId","status");
CREATE INDEX "Automation_businessId_triggerType_idx" ON "Automation"("businessId","triggerType");
CREATE TABLE "AutomationEvent" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"customerId" TEXT,"appointmentId" TEXT,"metadata" JSONB NOT NULL,"correlationId" TEXT NOT NULL,"causationId" TEXT,"depth" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AutomationEvent_business_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "AutomationEvent_businessId_id_key" ON "AutomationEvent"("businessId","id");
CREATE INDEX "AutomationEvent_businessId_eventType_occurredAt_idx" ON "AutomationEvent"("businessId","eventType","occurredAt");
CREATE TABLE "AutomationExecution" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"automationId" TEXT NOT NULL,"eventId" TEXT,"customerId" TEXT,"appointmentId" TEXT,"status" "AutomationExecutionStatus" NOT NULL DEFAULT 'PENDING',"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"failureReason" TEXT,"executionKey" TEXT NOT NULL,"result" JSONB,CONSTRAINT "AutomationExecution_business_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE RESTRICT,CONSTRAINT "AutomationExecution_automation_fkey" FOREIGN KEY ("businessId","automationId") REFERENCES "Automation"("businessId","id") ON DELETE RESTRICT,CONSTRAINT "AutomationExecution_event_fkey" FOREIGN KEY ("businessId","eventId") REFERENCES "AutomationEvent"("businessId","id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "AutomationExecution_businessId_executionKey_key" ON "AutomationExecution"("businessId","executionKey");
CREATE INDEX "AutomationExecution_automationId_startedAt_idx" ON "AutomationExecution"("automationId","startedAt");
CREATE INDEX "AutomationExecution_businessId_customerId_startedAt_idx" ON "AutomationExecution"("businessId","customerId","startedAt");
